 const cards=matches.length?'<div class="job-grid">'+matches.map(jobCard).join('')+'</div>':'<div class="empty"><strong>განცხადებები ვერ მოიძებნა</strong>შეცვალე ფილტრები ან სხვა სიტყვით სცადე ძებნა.<div><button class="btn btn-secondary btn-small" type="button" data-clear-all-schedule>ყველა ფილტრის გასუფთავება</button></div></div>';
