function workerProfileSkillEntries(profile){
 const stored=Array.isArray(profile?.skills)&&profile.skills.length?profile.skills:[profile?.subcategory||profile?.category].filter(Boolean),seen=new Set();
 return stored.map((value,index)=>{
  if(value&&typeof value==='object')return {main:String(value.main||''),sub:String(value.sub||'')};
  const skill=String(value||''),group=Object.entries(categoryGroups).find(([,subs])=>subs.includes(skill));
  if(group)return {main:group[0],sub:skill};
  if(categoryGroups[skill])return {main:skill,sub:''};
  if(index===0&&profile?.category)return {main:String(profile.category),sub:String(profile.subcategory||skill)};
  return {main:String(profile?.category||skill),sub:profile?.category?skill:''};
 }).filter(entry=>entry.main).filter(entry=>{const key=entry.main+'::'+entry.sub;if(seen.has(key))return false;seen.add(key);return true})
}
function workerSkillEntriesFromForm(form){
 const entries=[],seen=new Set();
 new FormData(form).getAll('workerSkill').forEach(value=>{try{const parsed=JSON.parse(value),entry={main:String(parsed.main||''),sub:String(parsed.sub||'')},key=entry.main+'::'+entry.sub;if(entry.main&&!seen.has(key)){seen.add(key);entries.push(entry)}}catch{}});
 return entries
}
