 const isAllSelected=main=>selected.some(entry=>entry.main===main&&!entry.sub),isSubSelected=(main,sub)=>isAllSelected(main)||selected.some(entry=>entry.main===main&&entry.sub===sub);
 if(!options)return;
 if(selectedMain&&!term){const available=(categoryGroups[selectedMain]||[]).filter(sub=>!isSubSelected(selectedMain,sub)),allOption=isAllSelected(selectedMain)?'':`<button type="button" class="category-option category-all" data-cat-all="${esc(selectedMain)}">ყველა — ${esc(selectedMain)}</button>`;options.innerHTML=allOption+available.map(sub=>`<button type="button" class="category-option" data-cat-subchoice="${esc(sub)}" data-cat-parent="${esc(selectedMain)}">→ ${esc(sub)}</button>`).join('')||'<div class="category-no-results">ყველა ქვეკატეგორია უკვე არჩეულია.</div>';widget.querySelector('[data-cat-back]').hidden=false;return}
 widget.querySelector('[data-cat-back]').hidden=!!term;const rows=[];
 for(const [main,subs]of Object.entries(categoryGroups)){const mainMatch=main.toLocaleLowerCase('ka').includes(term),matching=subs.filter(sub=>sub.toLocaleLowerCase('ka').includes(term)&&!isSubSelected(main,sub));if(!isAllSelected(main)&&(!term||mainMatch||matching.length)){rows.push(`<button type="button" class="category-option category-main" data-cat-open="${esc(main)}"><span>${categoryIcons[main]} ${esc(main)}</span><span>›</span></button>`);if(term&&(mainMatch||matching.length))rows.push(`<button type="button" class="category-option category-all" data-cat-all="${esc(main)}">ყველა — ${esc(main)}</button>`);if(term)for(const sub of matching)rows.push(`<button type="button" class="category-option category-sub" data-cat-subchoice="${esc(sub)}" data-cat-parent="${esc(main)}">→ ${esc(sub)}</button>`)}}
