document.addEventListener('submit',e=>{if(e.target.id!=='postForm')return;const form=e.target,d=new FormData(form),categorySelections=categoryPickerSelections(form.querySelector('#cat-post-category'));if(d.get('dateMode')!=='agreement'&&d.get('duration')==='multi-day'&&(!d.get('dateEnd')||d.get('dateEnd')<d.get('date'))){e.preventDefault();e.stopImmediatePropagation();document.getElementById('postMessage').innerHTML='<div class="error-msg">დასრულების თარიღი დაწყების თარიღს უნდა ემთხვეოდეს ან გვიან იყოს.</div>';return}setTimeout(()=>{const j=jobs[0];if(!j||j.title!==d.get('title'))return;j.district=j.area;j.categorySelections=categorySelections;if(categorySelections[0]){j.category=categorySelections[0].main;j.subcategory=categorySelections[0].sub}j.startTime=j.start;j.endTime=j.end;j.duration=d.get('duration');j.dateMode=d.get('dateMode')==='agreement'?'agreement':'date';if(j.dateMode==='agreement'){j.date='';j.dateEnd=''}else j.dateEnd=d.get('dateEnd')||'';j.paymentType=d.get('paymentType')||'daily';j.paymentAmount=j.paymentType==='negotiable'?null:Number(d.get('pay')||0);j.paymentMin=j.paymentAmount;j.paymentMax=j.paymentAmount;set('dge-jobs',jobs)},0)},true);

